    19	func TestOPFV1RewriteDoesNotLoseConcurrentCheckpointUpdate(t *testing.T) {
    20		t.Parallel()
    21	
    22		repoRoot, repo, oldTip := setupV1RepoInDir(t)
    23		tree := emptyTreeHash(t, repo)
    24		goGitTip := makeOrphanCommit(t, repo, tree, []plumbing.Hash{oldTip}, "go-git OPF rewrite")
    25		nativeTip := makeOrphanCommit(t, repo, tree, []plumbing.Hash{oldTip}, "native checkpoint write")
    26		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
    27	
    28		commitNative := prepareNativeRefUpdate(t, repoRoot, refName, oldTip, nativeTip)
    29		opfErr := atomicSetV1Ref(t.Context(), repo, oldTip, goGitTip)
    30		commitNative()
    31	
    32		finalRef, err := repo.Reference(refName, true)
    33		require.NoError(t, err)
    34		require.Equal(t, nativeTip, finalRef.Hash())
    35		require.Error(t, opfErr, "the OPF rewrite must not report success while a native update owns the ref lock")
    36	}
