    61	func prepareNativeRefUpdate(
    62		t *testing.T,
    63		repoRoot string,
    64		refName plumbing.ReferenceName,
    65		oldTip plumbing.Hash,
    66		newTip plumbing.Hash,
    67	) func() {
    68		t.Helper()
    69		ctx, cancel := context.WithTimeout(t.Context(), 10*time.Second)
    70		cmd := exec.CommandContext(ctx, "git", "update-ref", "--stdin")
    71		cmd.Dir = repoRoot
    72		cmd.Env = testutil.GitIsolatedEnv()
    73		stdin, err := cmd.StdinPipe()
    74		require.NoError(t, err)
    75		stdout, err := cmd.StdoutPipe()
    76		require.NoError(t, err)
    77		var stderr bytes.Buffer
    78		cmd.Stderr = &stderr
    79		require.NoError(t, cmd.Start())
    80		t.Cleanup(func() {
    81			cancel()
    82			if cmd.ProcessState == nil {
    83				if err := cmd.Wait(); err != nil {
    84					t.Logf("stopped unfinished git update-ref transaction: %v", err)
    85				}
    86			}
    87		})
    88	
    89		scanner := bufio.NewScanner(stdout)
    90		writeAndExpectGitUpdateRefResponse(t, stdin, scanner, "start", "start: ok")
    91		writeAndExpectGitUpdateRefResponse(t, stdin, scanner,
    92			fmt.Sprintf("update %s %s %s", refName, newTip, oldTip), "")
    93		writeAndExpectGitUpdateRefResponse(t, stdin, scanner, "prepare", "prepare: ok")
    94	
    95		return func() {
    96			writeAndExpectGitUpdateRefResponse(t, stdin, scanner, "commit", "commit: ok")
    97			require.NoError(t, stdin.Close())
    98			waitErr := cmd.Wait()
    99			require.NoError(t, waitErr, stderr.String())
   100		}
   101	}
